  input [15:0] fft_point_size_i;
  input [14:0] fft_whole_iterations_i;
  input [63:0] samples_rd_data_i, twiddles_rd_data_i;
  output busy_o, fft_done_o, samples_rd_en_o, samples_wr_en_o,
       twiddles_rd_en_o;
  output [14:0] samples_rd_addr_o, samples_wr_addr_o;
  output [63:0] samples_wr_data_o;
  output [13:0] twiddles_rd_addr_o;
  wire clk_i, rst_i, go_i;
  wire [15:0] fft_point_size_i;
  wire [14:0] fft_whole_iterations_i;
  wire [63:0] samples_rd_data_i, twiddles_rd_data_i;
